      setIsSyncingFromDirectory(true);
      toast.info("Syncing all 55 ARCL Master Formats from D:\\ARCL OBSERVATION REPORT AMU... ⚡");
      const res = await syncTemplatesFromDirectoryApi("D:\\ARCL OBSERVATION REPORT AMU");
