    items.forEach((it) => {
      const r = Number(it.rate) || 0;
      const q = Number(it.qty) || 1;
      const amt = it.amount !== undefined ? Number(it.amount) : r * q;
      taxable += amt;
      totalQty += q;
    });
    const cgst = Math.round(taxable * 0.09);
    const sgst = Math.round(taxable * 0.09);
